def m0(N):
    if N <= 0:
        return 0
    if N == 1:
        return 1
    # m_0(N) = m_0(floor(N/2)) + 1
    return m0(N // 2) + 1

N = 40
result = m0(N)
print(f"m0({N}) = {result}")

